python3 -c "
import json
with open('/app/resources/treasury_bulletin_1982_08.json', 'r') as f:
    data = json.load(f)

# Print the structure to understand it
print('Type:', type(data))
if isinstance(data, dict):
    print('Keys:', list(data.keys())[:20])
    for k, v in data.items():
        if '2-year' in str(k).lower() or '1984' in str(k):
            print(f'Key: {k}')
        if isinstance(v, dict):
            for k2, v2 in v.items():
                if '2-year' in str(k2).lower() or '1984' in str(k2):
                    print(f'  Sub-key: {k2}, Value: {v2}')
        elif isinstance(v, list):
            for item in v[:5]:
                if isinstance(item, dict):
                    for k2, v2 in item.items():
                        if '2-year' in str(k2).lower() or '1984' in str(k2):
                            print(f'  List item key: {k2}, Value: {v2}')
"
